COMMENT ON TABLE public.settings_versions IS 'Section-scoped sanitized settings history from activation onward; never credential history; retain for required audit.';
COMMENT ON TABLE public.application_telemetry IS 'Bounded sanitized outcome/duration telemetry; no prompts, keys or visitor identity; conservative 30 day default.';
CREATE OR REPLACE FUNCTION public.purge_expired_chats_bounded() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids text[]; removed integer; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; LOCK TABLE public.suggestion_requests IN SHARE ROW EXCLUSIVE MODE; LOCK TABLE public.live_chats IN SHARE ROW EXCLUSIVE MODE; SELECT array_agg(candidate_id) INTO ids FROM public.retention_candidates('chats',90,100); DELETE FROM public.live_chats WHERE id::text=ANY(ids); GET DIAGNOSTICS removed=ROW_COUNT; IF removed>0 THEN INSERT INTO public.admin_activity(actor_id,actor_email,action,target) VALUES('00000000-0000-0000-0000-000000000000','system','retention.chat_expiry','chats count='||removed::text); END IF; RETURN removed; END $$;
REVOKE ALL ON FUNCTION public.purge_expired_chats_bounded() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.purge_expired_chats_bounded() TO service_role;
CREATE OR REPLACE FUNCTION public.retention_policy_validation() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.data_type='chats' AND NEW.days<>90 THEN RAISE EXCEPTION 'Chats retain the 90 day policy'; END IF; RETURN NEW; END $$;
CREATE TRIGGER phase_six_retention_validate BEFORE INSERT OR UPDATE ON public.retention_policies FOR EACH ROW EXECUTE FUNCTION public.retention_policy_validation();